const s={page:'home',method:'bisection',tab:'learn',q:0,selected:null,answer:'',feedback:null,hint:false,wrong:0,reviewId:null,arenaIndex:0,arenaFilter:'all',combo:0,hearts:3,caseId:'tank',caseQ:0,sim:0,warning:loaded.warning,result:null,resultTab:'solution',error:'',source:'x^3 - x - 2 = 0',mode:'root',algorithm:'auto',a:'1',b:'2',x0:'1.5',x1:'2',g:'',min:'-40',max:'40',tolerance:'0.000001',maxIterations:'100',initial:'',historyOpen:false,guideIndex:0,guideAnswer:'',guideFeedback:null,comboIds:[],
 demo:'newton',demos:{newton:{x0:2.4,k:0},bisection:{a:0.5,b:2.5,k:0},secant:{x0:0.6,x1:2.6,k:0}},featTab:'roots',topicsTab:'roots',introStep:0,pathSel:null,confirm:null,pendingRestore:null};
const ICON={home:'M3 10 12 3l9 7v11h-6v-7H9v7H3Z',academy:'M4 4h6c2 0 2 2 2 2s0-2 2-2h6v15h-6c-2 0-2 2-2 2s0-2-2-2H4ZM12 6v15',arena:'M8 3h8v7a4 4 0 0 1-8 0ZM8 5H4v3a4 4 0 0 0 4 4M16 5h4v3a4 4 0 0 1-4 4M12 14v5M8 21h8',cases:'M3 7h18v14H3ZM8 7V3h8v4M3 12h18M10 12v3h4v-3',lab:'m4 7 5 5-5 5M12 17h8',progress:'M4 20V10M10 20V4M16 20v-7M22 20H2',review:'M20 7a9 9 0 1 0 1 8M20 2v5h-5',arrow:'M5 12h14m-5-5 5 5-5 5',check:'m5 12 4 4L19 6',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3Z',flame:'M12 21c-4 0-7-2.7-7-6.6 0-3.4 2.4-5.4 4-7.4.3 1.8 1.2 3 2.4 3.6C11 7 12.6 4.6 14.6 3c.2 2.6 1.6 4.4 3 6 1.2 1.4 1.4 3 1.4 4.4C19 18.3 16 21 12 21Z',back:'M19 12H5m5-5-5 5 5 5',lock:'M7 11V8a5 5 0 0 1 10 0v3M5 11h14v10H5Z',user:'M12 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8ZM4 21a8 8 0 0 1 16 0',close:'M6 6l12 12M18 6 6 18',book:'M3 5.5c3-1.4 6-1.2 9 1 3-2.2 6-2.4 9-1v13c-3-1.4-6-1.2-9 1-3-2.2-6-2.4-9-1ZM12 6.5v13',play:'M8 5v14l11-7Z',flag:'M5 21V4h11l-1.5 4L16 12H5',clock:'M12 7v5l3 2M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0Z',treino:'M6 7v10M3 9.5v5M18 7v10M21 9.5v5M6 12h12'};
const icon=(k,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${ICON[k]||ICON.spark}"/></svg>`;
const btn=(text,act,cls='primary',attrs='')=>`<button type="button" class="btn ${cls}" data-act="${act}" ${attrs}>${text}</button>`;
const tag=(text,cls='')=>`<span class="tag ${cls}">${text}</span>`;
const stars=n=>`<span class="stars" role="img" aria-label="${n} de 3 estrelas">${'★'.repeat(n)}<span>${'★'.repeat(3-n)}</span></span>`;
const method=id=>C.METHODS.find(m=>m.id===id);
const ROOTS=()=>C.METHODS.filter(m=>m.category!=='Sistemas lineares'),SYSTEMS=()=>C.METHODS.filter(m=>m.category==='Sistemas lineares'),isSysMethod=id=>id==='gauss'||id==='seidel';
const WORDS={3:'três',4:'quatro',5:'cinco',6:'seis',7:'sete',8:'oito',9:'nove',10:'dez'},words=n=>WORDS[n]||String(n),cap=t=>t.charAt(0).toUpperCase()+t.slice(1);
/* Número de verificações automáticas de tests/verify.cjs (o próprio teste confere este valor). */
const VERIFY_COUNT=1505;
const doneCount=id=>C.TASKS[id].filter((_,i)=>p.completed[`c:${id}:${i}`]).length;
const totalDone=()=>Object.keys(p.completed).length;
const courseDone=()=>C.METHODS.reduce((n,m)=>n+doneCount(m.id),0);
const due=()=>Object.keys(p.review).filter(id=>p.review[id].due<=P.day());
const dueAll=()=>due().length+(TR?TR.reviewDue():0);
const nextQ=id=>{const n=C.TASKS[id].findIndex((_,i)=>!p.completed[`c:${id}:${i}`]);return n<0?0:n;};
const nextMethod=()=>C.METHODS.find(m=>doneCount(m.id)<C.TASKS[m.id].length)||C.METHODS[0];
const level=()=>1+Math.floor(p.xp/200);
function persist(){if(!P.save(p,storage))s.warning='O navegador não conseguiu salvar. Exporte seu progresso para preservar esta sessão.';}
function resetQuestion(){s.selected=null;s.answer='';s.feedback=null;s.hint=false;s.wrong=0;}
function navigate(page,updateHash=true){s.page=page;s.confirm=null;resetQuestion();if(updateHash)history.replaceState(null,'','#'+page);render();window.scrollTo({top:0,behavior:'auto'});$('#main')?.focus({preventScroll:true});}

/* ---------- Ilustrações dos métodos (SVG próprio) ---------- */
function art(id,cls=''){const curve='M8 70 C34 69 52 60 66 44 S92 12 112 6';const map={
 bisection:`<rect class="a-band" x="10" y="14" width="100" height="10" rx="5"/><rect class="a-band" x="35" y="30" width="50" height="10" rx="5"/><rect class="a-band" x="47" y="46" width="26" height="10" rx="5"/><rect class="a-band strong" x="54" y="62" width="12" height="10" rx="5"/><path class="a-line" d="M60 8V76"/>`,
 newton:`<path class="a-axis" d="M6 52H114"/><path class="a-curve" d="${curve}"/><path class="a-dash" d="M50 76 104 14"/><circle class="a-dot" cx="94" cy="25" r="5"/><circle class="a-ring" cx="71" cy="52" r="5"/>`,
 secant:`<path class="a-axis" d="M6 52H114"/><path class="a-curve" d="${curve}"/><path class="a-solid" d="M30 76 110 0"/><circle class="a-dot" cx="52" cy="55" r="5"/><circle class="a-dot" cx="98" cy="12" r="5"/><circle class="a-ring" cx="58" cy="52" r="5"/>`,
 gauss:`${[0,1,2].map(r=>[0,1,2,3].map(c=>`<rect class="${c<r?'a-cell zero':c===3?'a-cell rhs':'a-cell'}" x="${16+c*24}" y="${8+r*24}" width="20" height="20" rx="6"/>`).join('')).join('')}`,
 falseposition:`<path class="a-axis" d="M6 52H114"/><path class="a-curve" d="${curve}"/><path class="a-solid" d="M8 70 L112 6"/><path class="a-dash" d="M37 52V62"/><circle class="a-dot" cx="8" cy="70" r="5"/><circle class="a-dot" cx="112" cy="6" r="5"/><circle class="a-ring" cx="37" cy="52" r="5"/>`,
 fixedpoint:`<path class="a-axis" d="M10 72 L110 8"/><path class="a-curve" d="M10 30 C40 34 70 42 110 50"/><path class="a-solid" d="M20 72 V32 H72.5 V42.5 H56 V39.2 H61.2 V40.2"/><circle class="a-dot" cx="20" cy="72" r="4"/><circle class="a-ring big" cx="60" cy="40" r="8"/>`,
 seidel:`<path class="a-solid" d="M12 70 L40 18 L58 58 L72 30 L80 48 L86 38"/><circle class="a-dot" cx="12" cy="70" r="4"/><circle class="a-dot" cx="40" cy="18" r="4"/><circle class="a-dot" cx="58" cy="58" r="4"/><circle class="a-dot" cx="72" cy="30" r="4"/><circle class="a-ring big" cx="84" cy="41" r="9"/>`};
 return `<svg class="art ${cls}" viewBox="0 0 120 80" aria-hidden="true">${map[id]||''}</svg>`;}

/* ---------- Moldura ---------- */
const LINKS=[['home','Início'],['academy','Trilhas'],['cases','Missões'],['arena','Arena'],['treino','Treino'],['lab','Terminal']];
const isActive=id=>s.page===id||s.page==='course'&&id==='academy'||s.page==='case'&&id==='cases';
function topbar(){const r=dueAll();return `<header class="topbar"><div class="topbar-inner"><a class="brand" href="#home" aria-label="Numera Academy, início"><span class="brand-mark" aria-hidden="true">∑</span><span class="brand-word">numera</span></a><nav class="top-links" aria-label="Principal">${LINKS.map(([id,name])=>`<button type="button" data-act="nav" data-page="${id}" class="top-link ${isActive(id)?'active':''}" ${isActive(id)?'aria-current="page"':''}>${name}</button>`).join('')}</nav><div class="top-meta"><button type="button" class="chip" data-act="nav" data-page="review" title="Caderno de revisão">${icon('review')}<span class="chip-label">Revisão</span>${r?`<b class="count">${r}</b>`:''}</button><button type="button" class="chip flame" data-act="nav" data-page="progress" title="${P.streak(p)} dias de sequência">${icon('flame')}<b>${P.streak(p)}</b></button><button type="button" class="chip dark" data-act="${totalDone()?'nav':'course'}" ${totalDone()?'data-page="progress"':`data-id="${nextMethod().id}"`}>${totalDone()?`✦ <b>${p.xp}</b> XP`:'Começar'}</button></div></div></header>`;}
function mobileNav(){return `<nav class="mobile-nav" aria-label="Navegação no celular">${[['home','Início'],['academy','Trilhas'],['cases','Missões'],['arena','Arena'],['treino','Treino'],['lab','Terminal'],['progress','Perfil']].map(([id,label])=>`<button type="button" data-act="nav" data-page="${id}" class="${isActive(id)?'active':''}">${icon(id==='progress'?'user':id)}<span>${label}</span></button>`).join('')}</nav>`;}
function footer(){const col=(t,items)=>`<div class="footer-col"><h3>${t}</h3>${items.map(([id,name])=>`<button type="button" data-act="nav" data-page="${id}">${name}</button>`).join('')}</div>`;return `<footer class="site-footer"><div class="wrap footer-inner"><div class="footer-brand"><span class="brand-mark" aria-hidden="true">∑</span><strong>numera</strong><p>Métodos numéricos para Modelagem Computacional, em lições interativas.</p></div>${col('Aprender',[['academy','Trilhas'],['cases','Missões'],['arena','Arena'],['treino','Treino']])}${col('Ferramentas',[['lab','Terminal'],['review','Revisão'],['progress','Progresso']])}<div class="footer-col"><h3>Referências</h3><a href="https://fncbook.com/newton/" target="_blank" rel="noopener">Driscoll &amp; Braun — Newton</a><a href="https://fncbook.com/secant/" target="_blank" rel="noopener">Secante e Bisseção</a><a href="https://www.netlib.org/linalg/html_templates/node14.html" target="_blank" rel="noopener">Netlib — Gauss-Seidel</a></div>${installEvt?`<div class="footer-install">${btn(icon('arrow')+' Instalar como app','install','ghost')}<span>Fica na tela inicial e abre mesmo sem internet.</span></div>`:''}<p class="footer-note">Projeto educacional de Modelagem Computacional. O escopo contém métodos numéricos para raízes e sistemas lineares; não resolve EDOs ou integrais. Dados e cálculos ficam no seu navegador. Versão 9.</p></div></footer>`;}
const heading=(eyebrow,title,subtitle,extra='')=>`<div class="page-head"><div><span class="eyebrow">${eyebrow}</span><h1 class="display">${title}</h1><p class="lead">${subtitle}</p></div>${extra?`<div class="page-head-extra">${extra}</div>`:''}</div>`;
const bar=(v,max=100,label='Progresso')=>`<div class="progress-track" role="progressbar" aria-valuemin="0" aria-valuemax="${max}" aria-valuenow="${v}" aria-label="${label}"><span style="width:${max?Math.min(100,v/max*100):0}%"></span></div>`;
/* Aba Treino (treino.js): recebe os utilitários da interface e devolve a página. */
function openInLab(cfg){s.source=cfg.source;s.mode=cfg.mode;s.algorithm=cfg.algorithm||'auto';s.g='';for(const k of ['a','b','x0','x1','g'])if(cfg[k]!==undefined&&cfg[k]!==null)s[k]=String(cfg[k]);if(cfg.initial!==undefined)s.initial=cfg.initial;s.result=null;s.error='';s.help=false;s.historyOpen=false;navigate('lab');}
const TR=window.NumeraTreinoUI?window.NumeraTreinoUI({safe,icon,btn,tag,bar,method,heading,tabs:(...a)=>tabs(...a),parseAnswer:v=>parseAnswer(v),openInLab,storage,render:()=>render(),nav:page=>{s.reviewId=null;navigate(page);}}):null;
function treinoCard(){if(!TR)return '';const t=TR.summary();return `<section class="card tr-progress"><span class="symbol small tone-newton" aria-hidden="true">${icon('treino')}</span><div><h3>Treino de diagnóstico</h3><p>${t.solved}/${TR.count} resolvidos · ${t.perfect} perfeitos ★ · ${t.rate===null?'nenhum diagnóstico ainda':t.rate+'% de diagnósticos certeiros'}${t.lastExam?` · última prova: ${t.lastExam.nota.toFixed(1).replace('.',',')}`:''}${t.reviewDue?` · ${t.reviewDue} para revisar`:''}</p></div>${btn('Abrir o Treino '+icon('arrow'),'nav','ghost','data-page="treino"')}</section>`;}

/* ---------- Demonstrações interativas da abertura ---------- */
const HERO_SOURCE='x^3 - x - 2';let heroFn=null;const heroF=()=>heroFn||(heroFn=M.parseFunction(HERO_SOURCE));
const ROOT=1.5213797068045676;
const G={W:560,H:320,L:44,R:18,T:16,B:34,lo:-1,hi:3,ylo:-6,yhi:22,min:-0.9,max:2.9};
const GX=x=>G.L+(x-G.lo)/(G.hi-G.lo)*(G.W-G.L-G.R),GY=y=>G.T+(G.yhi-y)/(G.yhi-G.ylo)*(G.H-G.T-G.B);
function demoBase(extra){const f=heroF();let path='',pen=false;for(let i=0;i<=160;i++){const x=G.lo+(G.hi-G.lo)*i/160,y=f(x);if(!Number.isFinite(y)||y>G.yhi+8||y<G.ylo-8){pen=false;continue;}path+=(pen?'L':'M')+GX(x).toFixed(1)+' '+GY(y).toFixed(1)+' ';pen=true;}
 const gx=[-1,0,1,2,3].map(v=>`<path class="g-grid" d="M${GX(v).toFixed(1)} ${G.T}V${G.H-G.B}"/><text class="g-label" x="${GX(v).toFixed(1)}" y="${G.H-12}" text-anchor="middle">${v}</text>`).join(''),gy=[-5,0,5,10,15,20].map(v=>`<path class="g-grid" d="M${G.L} ${GY(v).toFixed(1)}H${G.W-G.R}"/><text class="g-label" x="${G.L-8}" y="${(GY(v)+4).toFixed(1)}" text-anchor="end">${v}</text>`).join('');
 return `${gx}${gy}<path class="g-axis" d="M${G.L} ${GY(0).toFixed(1)}H${G.W-G.R}"/><text class="g-label" x="${G.W-G.R-4}" y="${(GY(0)-8).toFixed(1)}" text-anchor="end">x</text><g clip-path="url(#democlip)">${extra.under||''}<path class="g-curve" d="${path}"/>${extra.over||''}</g><circle class="g-root" cx="${GX(ROOT).toFixed(1)}" cy="${GY(0).toFixed(1)}" r="3.5"/>${extra.top||''}`;}
function demoState(){const f=heroF(),d=s.demos;
 if(s.demo==='bisection'){const {a,b}=d.bisection,fa=f(a),fb=f(b),m=(a+b)/2,fm=f(m),keepLeft=fa*fm<=0;return {kind:'bisection',a,b,fa,fb,m,fm,keepLeft,done:(b-a)/2<1e-4||Math.abs(fm)<1e-9};}
 if(s.demo==='secant'){const {x0,x1}=d.secant,f0=f(x0),f1=f(x1),den=f1-f0,x2=Math.abs(den)<1e-12?NaN:x1-f1*(x1-x0)/den;return {kind:'secant',x0,x1,f0,f1,x2,done:Math.abs(f1)<1e-9,out:!(x2>=G.min&&x2<=G.max)};}
 const {x0}=d.newton,fx=f(x0),dv=M.derivative(f,x0),flat=!Number.isFinite(dv)||Math.abs(dv)<0.15,x1=flat?NaN:x0-fx/dv;return {kind:'newton',x0,fx,d:dv,flat,x1,done:Math.abs(fx)<1e-6,out:!flat&&!(x1>=G.min&&x1<=G.max)};}
function demoPlot(){const st=demoState(),f=heroF();let svg='',read='',note='';
 if(st.kind==='newton'){const {x0,fx,d,flat,x1}=st;
  svg=demoBase({over:`${Number.isFinite(d)?`<path class="g-tangent" d="M${GX(G.lo).toFixed(1)} ${GY(fx+d*(G.lo-x0)).toFixed(1)}L${GX(G.hi).toFixed(1)} ${GY(fx+d*(G.hi-x0)).toFixed(1)}"/>`:''}${fx<=G.yhi&&fx>=G.ylo?`<path class="g-guide" d="M${GX(x0).toFixed(1)} ${GY(0).toFixed(1)}V${GY(fx).toFixed(1)}"/><circle class="g-point" cx="${GX(x0).toFixed(1)}" cy="${GY(fx).toFixed(1)}" r="5"/>`:''}`,top:`${!flat&&!st.out?`<circle class="g-next" cx="${GX(x1).toFixed(1)}" cy="${GY(0).toFixed(1)}" r="6"/><text class="g-tag" x="${GX(x1).toFixed(1)}" y="${(GY(0)+22).toFixed(1)}" text-anchor="middle">x₁</text>`:''}<g class="g-handle" transform="translate(${GX(x0).toFixed(1)} ${GY(0).toFixed(1)})"><circle r="16" class="g-handle-halo"/><circle r="8" class="g-handle-dot"/></g><text class="g-tag strong" x="${GX(x0).toFixed(1)}" y="${(GY(0)-16).toFixed(1)}" text-anchor="middle">x₀</text>`});
  read=`<div><span>x₀</span><b>${short(x0)}</b></div><div><span>f(x₀)</span><b>${short(fx)}</b></div><div><span>f′(x₀)</span><b>${short(d)}</b></div><div class="accent"><span>x₁ = x₀ − f/f′</span><b>${flat?'—':short(x1)}</b></div>`;
  note=flat?'A tangente está quase horizontal: o próximo palpite iria para muito longe. É uma armadilha do Newton-Raphson.':st.done?'Chegamos à raiz: |f(x)| já é praticamente zero.':st.out?`O próximo palpite, x₁ ≈ ${short(x1)}, cai fora do gráfico. Um x₀ ruim pode afastar o método da raiz.`:`A tangente em x₀ cruza o eixo em x₁ ≈ ${short(x1)}. Esse é o próximo palpite. Arraste o ponto azul.`;}
 else if(st.kind==='bisection'){const {a,b,fa,fb,m,fm}=st;
  svg=demoBase({under:`<rect class="g-band" x="${GX(a).toFixed(1)}" y="${G.T}" width="${Math.max(1,GX(b)-GX(a)).toFixed(1)}" height="${G.H-G.T-G.B}"/>`,over:`<circle class="g-point" cx="${GX(a).toFixed(1)}" cy="${GY(Math.max(G.ylo,Math.min(G.yhi,fa))).toFixed(1)}" r="4.5"/><circle class="g-point" cx="${GX(b).toFixed(1)}" cy="${GY(Math.max(G.ylo,Math.min(G.yhi,fb))).toFixed(1)}" r="4.5"/><path class="g-guide" d="M${GX(m).toFixed(1)} ${G.T}V${G.H-G.B}"/>`,top:`<circle class="g-next" cx="${GX(m).toFixed(1)}" cy="${GY(0).toFixed(1)}" r="6"/><text class="g-tag" x="${GX(m).toFixed(1)}" y="${(GY(0)+22).toFixed(1)}" text-anchor="middle">m</text>`});
  read=`<div><span>a</span><b>${short(a)}</b></div><div><span>b</span><b>${short(b)}</b></div><div><span>m = (a+b)/2</span><b>${short(m)}</b></div><div class="accent"><span>f(m)</span><b>${short(fm)}</b></div>`;
  note=st.done?`O intervalo ficou com largura ${short(b-a)}: o ponto médio está a menos de ${short((b-a)/2)} da raiz.`:`f(m) ${fm<0?'é negativo':'é positivo'}. A raiz fica na metade ${st.keepLeft?'da esquerda, [a, m]':'da direita, [m, b]'}, onde o sinal muda.`;}
 else{const {x0,x1,f0,f1,x2}=st,slope=(f1-f0)/(x1-x0);
  svg=demoBase({over:`<path class="g-tangent solid" d="M${GX(G.lo).toFixed(1)} ${GY(f0+slope*(G.lo-x0)).toFixed(1)}L${GX(G.hi).toFixed(1)} ${GY(f0+slope*(G.hi-x0)).toFixed(1)}"/>${[[x0,f0],[x1,f1]].filter(([,y])=>y<=G.yhi&&y>=G.ylo).map(([x,y])=>`<circle class="g-point" cx="${GX(x).toFixed(1)}" cy="${GY(y).toFixed(1)}" r="5"/>`).join('')}`,top:`${!st.out&&Number.isFinite(x2)?`<circle class="g-next" cx="${GX(x2).toFixed(1)}" cy="${GY(0).toFixed(1)}" r="6"/><text class="g-tag" x="${GX(x2).toFixed(1)}" y="${(GY(0)+22).toFixed(1)}" text-anchor="middle">x₂</text>`:''}`});
  read=`<div><span>x₀</span><b>${short(x0)}</b></div><div><span>x₁</span><b>${short(x1)}</b></div><div><span>f(x₁)</span><b>${short(f1)}</b></div><div class="accent"><span>x₂</span><b>${short(x2)}</b></div>`;
  note=st.done?'Chegamos à raiz sem calcular nenhuma derivada.':st.out?`O próximo ponto, x₂ ≈ ${short(x2)}, sai do gráfico. Recomece com outros pontos.`:`A reta pelos dois últimos pontos cruza o eixo em x₂ ≈ ${short(x2)}. A Secante troca a derivada por essa inclinação.`;}
 return `<svg class="demo-svg ${st.kind==='newton'?'draggable':''}" viewBox="0 0 ${G.W} ${G.H}" role="img" aria-label="Gráfico de f(x) = x³ − x − 2 com o passo atual do método"><defs><clipPath id="democlip"><rect x="${G.L}" y="${G.T}" width="${G.W-G.L-G.R}" height="${G.H-G.T-G.B}"/></clipPath></defs>${svg}</svg><div class="demo-readout">${read}</div><p class="demo-note" role="status">${note}</p>`;}
const DEMOS=[['newton','Newton-Raphson'],['bisection','Bisseção'],['secant','Secante']];
function demoStepLabel(){return s.demo==='bisection'?'Dividir ao meio':s.demo==='secant'?'Traçar a próxima secante':'Dar o próximo passo';}
function demoCount(){const k=s.demos[s.demo].k;return k?`${k} ${k===1?'passo':'passos'}`:s.demo==='newton'?'Arraste o ponto azul':'Clique para avançar';}
function heroWidget(){return `<div class="demo-tabs" role="group" aria-label="Escolha o método da demonstração">${DEMOS.map(([id,t])=>`<button type="button" data-act="demo" data-id="${id}" class="${s.demo===id?'active':''}" aria-pressed="${s.demo===id}">${t}</button>`).join('')}</div><div class="demo-fn"><code>f(x) = x³ − x − 2</code><span class="autoplay" id="autoplay-label">${demoAuto.on?'Demonstração automática':''}</span></div><div id="demo-plot">${demoPlot()}</div><div class="demo-controls">${s.demo==='newton'?`<label class="sr-only" for="demo-x0">Posição do palpite x₀</label><input id="demo-x0" type="range" min="${G.min}" max="${G.max}" step="0.01" value="${s.demos.newton.x0}">`:''}<div class="demo-buttons">${btn(demoStepLabel(),'demo-step','primary')}${btn('Recomeçar','demo-reset','ghost')}<span class="demo-count" id="demo-count">${demoCount()}</span></div></div>`;}
function refreshDemo(){const plot=$('#demo-plot');if(plot)plot.innerHTML=demoPlot();const range=$('#demo-x0');if(range&&document.activeElement!==range)range.value=s.demos.newton.x0;const count=$('#demo-count');if(count)count.textContent=demoCount();const lab=$('#autoplay-label');if(lab)lab.textContent=demoAuto.on?'Demonstração automática':'';}
function setNewtonX(x,round=true){const v=Math.min(G.max,Math.max(G.min,x));s.demos.newton.x0=round?Math.round(v*1000)/1000:v;}
function demoReset(id=s.demo){s.demos[id]=id==='newton'?{x0:2.4,k:0}:id==='bisection'?{a:0.5,b:2.5,k:0}:{x0:0.6,x1:2.6,k:0};}
function demoStep(){const st=demoState(),d=s.demos[s.demo];if(st.done)return false;
 if(st.kind==='newton'){if(st.flat||st.out)return false;setNewtonX(st.x1,false);}
 else if(st.kind==='bisection'){if(st.keepLeft)d.b=st.m;else d.a=st.m;}
 else{if(st.out||!Number.isFinite(st.x2))return false;d.x0=d.x1;d.x1=st.x2;}
 d.k++;return true;}
/* Demonstração automática: roda sozinha até a pessoa interagir. Desligada com movimento reduzido. */
const demoAuto={on:false,timer:null};
function stopAuto(){demoAuto.on=false;if(demoAuto.timer){clearTimeout(demoAuto.timer);demoAuto.timer=null;}const lab=$('#autoplay-label');if(lab)lab.textContent='';}
function autoTick(){demoAuto.timer=null;if(!demoAuto.on)return;if(!$('#demo-plot')){demoAuto.on=false;return;}
 if(!demoStep()){const i=DEMOS.findIndex(([id])=>id===s.demo);s.demo=DEMOS[(i+1)%DEMOS.length][0];demoReset(s.demo);const w=$('#hero-widget');if(w)w.innerHTML=heroWidget();}else refreshDemo();
 demoAuto.timer=setTimeout(autoTick,1700);}
function startAuto(){if(demoAuto.on||typeof window.matchMedia!=='function')return;try{if(window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;}catch(_){return;}demoAuto.on=true;demoAuto.timer=setTimeout(autoTick,2200);}

/* ---------- Visuais das seções ---------- */
function bisectionPreview(){const r=M.bisection(M.parseFunction('x^3-x-2'),1,2,{tolerance:1e-8,maxIterations:60}),rows=r.iterations.filter(t=>Number.isFinite(t.a)).slice(0,6),X=x=>20+(x-1)*340;return `<svg class="mini-svg" viewBox="0 0 400 ${rows.length*30+34}" role="img" aria-label="Intervalos da Bisseção encolhendo em torno da raiz">${rows.map((t,i)=>`<rect class="mini-band" x="${X(t.a).toFixed(1)}" y="${10+i*30}" width="${Math.max(2,X(t.b)-X(t.a)).toFixed(1)}" height="16" rx="8"/><text class="g-label" x="392" y="${23+i*30}" text-anchor="end">passo ${i+1}</text>`).join('')}<path class="g-root-line" d="M${X(r.root).toFixed(1)} 4V${rows.length*30+12}"/><text class="g-label" x="${X(r.root).toFixed(1)}" y="${rows.length*30+28}" text-anchor="middle">raiz ≈ ${short(r.root)}</text></svg>`;}
function gaussPreview(){const {A,b}=M.parseSystem(C.DEEP.gauss.system),r=M.gauss(A,b,{tolerance:1e-8,maxIterations:80}),first=r.iterations[0].matrix,mid=(r.iterations.find((t,i)=>i>0&&t.matrix&&t.matrix.every((row,k)=>row.slice(0,k).every(v=>Math.abs(v)<1e-12)))||r.iterations[r.iterations.length-1]).matrix;const mini=m=>`<table class="mini-matrix"><tbody>${m.map((row,k)=>`<tr>${row.map((v,j)=>`<td class="${j===row.length-1?'rhs':j<k&&Math.abs(v)<1e-12?'zero':''}">${short(v)}</td>`).join('')}</tr>`).join('')}</tbody></table>`;return `<div class="gauss-preview">${mini(first)}<span class="arrow-big" aria-hidden="true">→</span>${mini(mid)}</div><p class="media-caption">Escalonamento real do motor: zeros abaixo da diagonal, depois retrossubstituição. Solução: ${r.root.map((v,i)=>`x${i+1} = ${short(v)}`).join(', ')}.</p>`;}
function seidelPreview(){const {A,b}=M.parseSystem(C.DEEP.seidel.system),r=M.seidel(A,b,A.map(()=>0),{tolerance:1e-8,maxIterations:80}),rows=r.iterations.filter(t=>Number.isFinite(t.residual)&&t.residual>0).slice(0,9),max=Math.log10(rows[0]?.residual||1),min=Math.min(-9,Math.log10(rows[rows.length-1]?.residual||1e-9));const H=150,W=380,Y=v=>14+(max-Math.log10(v))/(max-min||1)*(H-34);return `<svg class="mini-svg" viewBox="0 0 ${W} ${H}" role="img" aria-label="Resíduo do Gauss-Seidel caindo a cada iteração">${rows.map((t,i)=>{const x=24+i*((W-48)/Math.max(1,rows.length-1));return `<rect class="mini-bar" x="${(x-10).toFixed(1)}" y="${Y(t.residual).toFixed(1)}" width="20" height="${(H-20-Y(t.residual)).toFixed(1)}" rx="5"/><text class="g-label" x="${x.toFixed(1)}" y="${H-4}" text-anchor="middle">${t.i}</text>`;}).join('')}</svg><p class="media-caption">Resíduo máximo por iteração, em escala logarítmica. Cada coluna é uma iteração real do Gauss-Seidel.</p>`;}
function questionMock(task){return `<div class="mock-q"><span class="tag">Raciocínio</span><p class="mock-title">${safe(task.q)}</p><div class="mock-choices">${task.options.map((o,i)=>`<span class="${i===task.answer?'right':''}"><b>${String.fromCharCode(65+i)}</b>${safe(o)}</span>`).join('')}</div><div class="mock-sheet"><b>Correto!</b> ${safe(task.explain)}</div></div>`;}
function reviewMock(){return `<div class="review-mock">${[['1 dia','Primeira revisão'],['3 dias','Acertou sem ajuda'],['7 dias','Acertou de novo'],['14 dias','Fixado']].map(([d,t],i)=>`<div class="rm-step ${i<2?'done':''}"><b>${d}</b><span>${t}</span></div>`).join('')}</div><p class="media-caption">Errou ou pediu dica? A questão volta no caderno de revisão. Cada acerto sem ajuda afasta a próxima revisão.</p>`;}
function calendarMock(){const days=['S','T','Q','Q','S','S','D'],on=[1,1,0,1,1,1,0];return `<div class="cal-mock">${days.map((d,i)=>`<div class="${on[i]?'on':''}"><span>${d}</span><b>${on[i]?'✓':'·'}</b></div>`).join('')}</div><div class="goal-mock"><span>Objetivo do dia</span><b>3 atividades diferentes</b>${bar(2,3,'Exemplo de objetivo diário')}<small>Exemplo ilustrativo</small></div>`;}
let teaserCache=null;
function teaserScreen(){if(!teaserCache){try{const r=M.smartRoot('x^3 - x - 2 = 0',{tolerance:1e-6,maxIterations:100,min:-40,max:40}),sys=M.parseSystem('2x + y = 5\nx + 3y = 6'),q=M.autoSystem(sys.A,sys.b,sys.A.map(()=>0),{tolerance:1e-6,maxIterations:100});teaserCache={r,q,vars:sys.variables};}catch(_){teaserCache={};}}const {r,q,vars}=teaserCache;if(!r||!q)return '';const n=updates(r);return `<div class="teaser-screen" role="group" aria-label="Exemplo calculado agora pelo motor"><div class="term-line"><span>λ</span> x^3 - x - 2 = 0</div><div class="term-out">método escolhido <b>${method(r.method).title}</b></div><div class="term-out">x ≈ <b>${num(r.root)}</b></div><div class="term-out">|f(x)| ≈ ${num(r.residual)} · ${n} ${n===1?'atualização':'atualizações'}</div><div class="term-line dim"><span>λ</span> 2x + y = 5 ; x + 3y = 6</div><div class="term-out">${q.root.map((v,i)=>`${vars?.[i]||'x'+(i+1)} = <b>${num(v)}</b>`).join(' · ')} · ${method(q.method).title}</div></div>`;}

